'use strict'

import { SPRITE_TEXT_COLOR_WHITE, TILE_HEIGHT, TILE_WIDTH } from '../constant'
import textManager from '../service/text-manager'
import hitboxManager from '../service/hitbox-manager'

class Item {
  // text: what the character says once Link paid for it (pay_to_talk caves); rupees: what it gives
  // (the rupee of a secret cave)
  constructor (name, column, line, x, y, width, height, sprite, price, { text, rupees } = {}) {
    this.name = name
    this.column = column
    this.line = line
    this.x = x
    this.y = y
    this.width = width
    this.height = height
    this.sprite = sprite
    this.price = price
    this.text = text
    this.rupees = rupees
    this.hitbox = hitboxManager.compute({ x, y, width, height })
    this.enabled = true
    // Written under it (price, gain of the money game…); set by the map
    this.label = price ? price.toString() : undefined
    // False once the game or the talk is over: still shown, no longer picked
    this.pickable = true
  }

  init () {
    this.sprite.start()
    this.enabled = true
    this.pickable = true
  }

  reset () {
    this.sprite.stop()
  }

  // At its place on the map, or elsewhere (in the top menu once picked)
  draw (context, x = this.x, y = this.y) {
    if (!this.enabled) {
      return
    }

    this.sprite.draw(context, x, y, this.width, this.height)

    if (this.label) {
      textManager.draw(context, this.label, SPRITE_TEXT_COLOR_WHITE, this.x - 0.5 * TILE_WIDTH, this.y + 1.5 * TILE_HEIGHT, TILE_WIDTH * 1.5, TILE_HEIGHT, 'right')
    }
  }

  clone () {
    return new Item(this.name, this.column, this.line, this.x, this.y, this.width, this.height, this.sprite, this.price, { text: this.text, rupees: this.rupees })
  }
}

export { Item }
